  "Reciprocity": {"Explanation": "The email asks employees to participate in the pulse survey and promises that their survey responses will bring improvements to ETS, implying that the company values their input and is willing to make changes based on their feedback."},
  "Scarcity": {"Explanation": "The email creates a sense of urgency by specifying a deadline (between now and Friday, Oct. 27) for employees to complete the survey, implying that participation is time-sensitive."},
  "Authority": {"Explanation": "Not present"},
  "Commitment/Consistency": {"Explanation": "Not present"},
  "Liking": {"Explanation": "The email uses a friendly tone and expresses gratitude to employees who have already completed the survey, attempting to build a positive relationship with the reader."},
  "Social proof": {"Explanation": "The email mentions that nearly 27% of all ETS employees have completed the pulse survey, implying that many of their colleagues have already participated and encouraging the reader to do the same."}
}

